'use strict';
// HTMLへ入れる検索文字列や資料由来の文字は必ずエスケープする。
const R=window.RPG, $=id=>document.getElementById(id);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=n=>new Intl.NumberFormat('ja-JP',{maximumFractionDigits:3}).format(n);
const NAV=[['home','冒険の手引き','⌂'],['world','世界・敵','◇'],['player','プレイヤー育成','↗'],['production','生産スキル','▤'],['cooking','料理・食材','◉'],['equipment','武器・装備','†'],['combat','戦闘・計算機','∑']];
const DEPTHS=[[1,20],[10,35],[20,50],[30,65],[40,80],[50,100],[60,100],[70,100],[80,100],[90,100]],PROGRESS=[100,200,350,700,1000,3000,3400,5200,7700];
const SPECIALS={invert:'反転',extra:'追加抽選',amplify:'増幅+1',amplify2:'増幅+2',reduce:'減少',prolong:'持続'};
const CATEGORIES={crop:'作物',fish:'魚',meat:'肉',other:'その他'},GEAR_CATEGORIES={offense:'攻撃',defense:'防御',survival:'移動・生存',special:'特殊能力',curse:'呪い'};
const heading=(e,t,d)=>`<div class="eyebrow">${e}</div><h1>${t}</h1><p class="lead">${d}</p>`;
const table=(heads,rows)=>`<div class="table-wrap" tabindex="0" aria-label="${esc(heads.join('・'))}の表"><table><thead><tr>${heads.map(h=>`<th scope="col">${h}</th>`).join('')}</tr></thead><tbody>${rows.map(row=>`<tr>${row.map(c=>`<td>${c??'—'}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;
const formula=t=>`<pre class="formula">${esc(t)}</pre>`;
const source=t=>`<p class="source">仕様基準 1.16.1 · 出典：${esc(t)}</p>`;
const rarity=r=>`<span class="rare-${r.id}">${esc(r.name)}</span>`;
const options=o=>Object.entries(o).map(([v,l])=>`<option value="${esc(v)}">${esc(l)}</option>`).join('');
const toc=items=>`<nav class="toc" aria-label="このページの目次">${items.map(([id,t])=>`<a href="#${currentPage}?section=${id}">${t}</a>`).join('')}</nav>`;
const range=(a,b)=>a===b?String(a):`${a}〜${b}`;
const normalize=s=>String(s).normalize('NFKC').toLocaleLowerCase('ja').replace(/[ァ-ヶ]/g,c=>String.fromCharCode(c.charCodeAt(0)-0x60));
const matches=(text,q)=>normalize(q).trim().split(/\s+/).every(w=>normalize(text).includes(w));
let currentPage='home',currentParams=new URLSearchParams(),foodPage=1,searchLimit=40;
const HOME=$('main').innerHTML;
function effectInfo(x){const [kind,id,a,b,s1,s2,w]=x, stat=R.gear.find(g=>g.id===id);let name,strength,bad=false;
  if(kind==='v'){name=R.effects[id].name;strength=range(['','I','II','III','IV','V','VI','VII'][a]||a,['','I','II','III','IV','V','VI','VII'][b]||b);bad=!!R.effects[id].bad}
  else if(kind==='s'){name=stat.name;const u=R.units[id]||1,suffix=stat.valueType==='percent'?'%':stat.valueType==='seconds'?'秒':stat.valueType==='level'?'段':'';strength='+'+range(a*u,b*u)+suffix}
  else if(kind==='p'){name=R.powers[id].name;strength='Lv'+range(a,b)}else if(kind==='a'){name=R.alloc[id];strength='+'+range(a,b)}else{name='経験値';strength='×'+range(1+a*.25,1+b*.25)}
  return {name,strength,time:range(s1,s2)+'秒',weight:w,bad,kind};
}
function setParam(values){for(const [k,v]of Object.entries(values)){if(v)currentParams.set(k,v);else currentParams.delete(k)}const q=currentParams.toString();history.replaceState(null,'','#'+currentPage+(q?'?'+q:''));}
function empty(){return '<div class="empty"><h3>該当する項目がありません</h3><p>検索語を短くするか、絞り込みを解除してください。</p></div>'}
function foodCard(f){const total=f.pool.reduce((s,p)=>s+p[6],0);return `<article class="food" id="food-${esc(f.id.replace(/[^a-z0-9]/gi,'-'))}"><h3>${esc(f.name)}</h3><span class="badge">${CATEGORIES[f.category]}</span>${f.special?`<span class="badge good">${SPECIALS[f.special]}</span>`:''}<div class="meta">栄養 ${f.nutrition} ／ 容器：${esc(({ 'minecraft:bowl':'ボウル','minecraft:bucket':'バケツ','minecraft:glass_bottle':'ガラス瓶' })[f.container]||'なし')}</div><ul>${f.pool.map(p=>{const e=effectInfo(p);return `<li><div class="pool-row"><span class="${e.bad?'bad':''}">${esc(e.name)} <strong>${e.strength}</strong></span><small>${fmt(e.weight/total*100)}% <span class="meta">重み${e.weight}</span></small></div><span class="meta">持続 ${e.time}</span></li>`}).join('')||'<li>固有プールなし。追加抽選プールから効果を選びます。</li>'}</ul><details><summary class="small">アイテムID</summary><span class="small">${esc(f.id)}</span></details></article>`}
function filterFoods(){const q=$('food-query').value,cat=$('food-category').value,sp=$('food-special').value;return R.foods.filter(f=>(!cat||f.category===cat)&&(!sp||f.special===sp)&&matches([f.name,f.id,...f.pool.map(p=>effectInfo(p).name)].join(' '),q))}
function renderFoods(){const arr=filterFoods(),pages=Math.max(1,Math.ceil(arr.length/12));foodPage=Math.max(1,Math.min(foodPage,pages));$('food-count').textContent=`${arr.length}件 / 全80食材${arr.length?` · ${(foodPage-1)*12+1}〜${Math.min(foodPage*12,arr.length)}件を表示`:''}`;$('food-results').innerHTML=arr.length?arr.slice((foodPage-1)*12,foodPage*12).map(foodCard).join(''):empty();$('food-pages').innerHTML=pages>1?`<button id="food-prev" ${foodPage===1?'disabled':''}>前へ</button><span>${foodPage} / ${pages}</span><button id="food-next" ${foodPage===pages?'disabled':''}>次へ</button>`:'';if(pages>1){$('food-prev').onclick=()=>{foodPage--;renderFoods();$('ingredients').scrollIntoView()};$('food-next').onclick=()=>{foodPage++;renderFoods();$('ingredients').scrollIntoView()}}}
function bindFoods(){$('food-query').value=currentParams.get('q')||'';$('food-category').value=currentParams.get('category')||'';$('food-special').value=currentParams.get('special')||'';foodPage=1;for(const id of ['food-query','food-category','food-special'])$(id).addEventListener('input',()=>{foodPage=1;setParam({q:$('food-query').value,category:$('food-category').value,special:$('food-special').value});renderFoods()});$('food-reset').onclick=()=>{for(const id of ['food-query','food-category','food-special'])$(id).value='';setParam({q:'',category:'',special:''});foodPage=1;renderFoods()};renderFoods()}
function gearValue(g,i){if(g.id==='soulbound')return i<4?'このレア度では付与なし':`追加抽選 ${i===6?10:5}%`;if(g.valueType==='none'||!g.profile)return '数値なし';const p=R.profiles[g.profile][i],s=g.valueType==='percent'?'%':g.valueType==='seconds'?'秒':g.valueType==='level'?'段':'';return range(p[0],p[1])+s}
function renderGear(){const type=$('gear-type').value,cat=$('gear-category').value,q=$('gear-query').value,r=$('gear-rarity').value,i=R.rarities.findIndex(x=>x.id===r);const arr=R.gear.filter(g=>(!type||g.types.includes(type)||g.id==='soulbound')&&(!cat||g.category===cat)&&matches(g.name+' '+g.description,q));$('gear-count').textContent=`${arr.length}件 / 全62能力 · ${R.rarities[i].name}の数値範囲`;$('gear-results').innerHTML=arr.length?arr.map(g=>`<details class="gear-entry"><summary><span class="${g.category==='curse'?'bad':g.category==='special'?'good':''}">${esc(g.name)}</span> <span class="badge">${GEAR_CATEGORIES[g.category]}</span> <span class="rare-${r}">${gearValue(g,i)}</span></summary><p>${esc(g.description)}</p><p class="small">対象：${g.id==='soulbound'?'レジェンド以上の装備で追加抽選':g.types.map(t=>R.gearTypes[t]).join('・')}<br>抽選重み：${g.weight??'追加抽選のみ'}${g.cap!==null?' ／ 装備合計の上限：'+g.cap+(g.valueType==='percent'?'%':''):''}</p>${g.id==='soulbound'?'<p>レジェンド5%・ミシック5%・ユニーク10%。自然の能力枠とは別の追加抽選です。</p>':table(['レア度','能力値'],R.rarities.map((r,n)=>[rarity(r),gearValue(g,n)]))}</details>`).join(''):empty()}
function bindGear(){$('gear-query').value=currentParams.get('q')||'';$('gear-type').value=currentParams.get('type')||'';$('gear-category').value=currentParams.get('category')||'';$('gear-rarity').value=currentParams.get('rarity')||'common';if(!$('gear-rarity').value)$('gear-rarity').value='common';for(const id of ['gear-query','gear-type','gear-category','gear-rarity'])$(id).addEventListener('input',()=>{setParam({q:$('gear-query').value,type:$('gear-type').value,category:$('gear-category').value,rarity:$('gear-rarity').value});renderGear()});$('gear-reset').onclick=()=>{['gear-query','gear-type','gear-category'].forEach(id=>$(id).value='');$('gear-rarity').value='common';setParam({q:'',type:'',category:'',rarity:''});renderGear()};renderGear();if(currentParams.get('q'))document.querySelector('#gear-results details')?.setAttribute?.('open','')}
function production(){return `${heading('PROFESSIONS & SKILLS','生産スキル','9つの分野をそれぞれ育て、Lv10ごとに2つのスキルから1つを選ぶ。')}<div class="panel"><h3>各分野Lv1〜50。スキルは各段階で二択。</h3><p>常時効果はLv1で0、Lv50で最大。Lv10・20・30・40・50で、AかBのどちらか1つを選べます。</p><p class="small">技能忘却の宝珠：全分野の選択をリセット。技能転換の宝珠：1段階だけもう一方へ変更。どちらもレベルと経験値は残ります。</p></div><div class="filters"><input id="skill-query" type="search" aria-label="スキルを検索" placeholder="スキル名・効果・操作を検索"><select id="skill-disc" aria-label="生産分野"><option value="">すべての分野</option>${R.disciplines.map(d=>`<option value="${d.id}">${d.name}</option>`).join('')}</select><select id="skill-level" aria-label="スキル習得レベル"><option value="">すべての段階</option>${[10,20,30,40,50].map(n=>`<option value="${n}">Lv${n}</option>`).join('')}</select><button id="skill-reset">リセット</button></div><div id="skill-passive"></div><div id="skill-count" class="count" aria-live="polite"></div><div class="skill-grid" id="skill-results"></div><h2>常時効果と経験値の入り方</h2>${R.disciplines.map(d=>`<details><summary>${d.name} · ${d.passive}</summary><p>${d.description} 最大${d.max}${d.unit}。</p><h3>経験値</h3><p>${d.xp}</p></details>`).join('')}<h2>レベルアップに必要な経験値</h2>${formula('次のレベルの必要経験値 = round(6 × 現在Lv^1.3)\n常時効果の値 = 最大値 × (現在Lv − 1) ÷ 49')}${table(['到達レベル','累計経験値'],[10,20,30,40,50].map(n=>[n,fmt(Array.from({length:n-1},(_,i)=>Math.round(6*(i+1)**1.3)).reduce((a,b)=>a+b,0))]))}<p class="small">金の卵を食べると10分間、生産・プレイヤー・バニラ経験値が2倍になります。</p>${source('生産スキル一覧 §0〜9／仕様書 1.16.1・1.16.0・1.11.0／実装済みの各生産設計案')}`}
function renderSkills(){const disc=$('skill-disc').value,level=$('skill-level').value,q=$('skill-query').value,arr=R.skills.filter(s=>(!disc||s.disc===disc)&&(!level||s.level===Number(level))&&matches(s.name+' '+s.summary+' '+s.detail+' '+s.operation,q)).sort((a,b)=>R.disciplines.findIndex(d=>d.id===a.disc)-R.disciplines.findIndex(d=>d.id===b.disc)||a.level-b.level||a.side.localeCompare(b.side));const d=R.disciplines.find(d=>d.id===disc);$('skill-passive').innerHTML=d?`<div class="note"><strong>${d.name}の常時効果：${d.passive}</strong><br>${d.description} Lv50で最大${d.max}${d.unit}。</div>`:'';$('skill-count').textContent=`${arr.length}件 / 全90スキル · 同じ分野・同じレベルではAかBを選択`;$('skill-results').innerHTML=arr.length?arr.map(s=>`<article class="skill" id="skill-${s.id}"><div class="eyebrow">${esc(s.discipline)} / Lv${s.level} / ${s.side.toUpperCase()}</div><h3>${esc(s.name)} <span class="badge">${esc(s.kind)}</span></h3><p>${esc(s.summary)}</p><p class="operation">操作：${esc(s.operation)}</p><p class="numbers">${esc(s.numbers)}</p><details><summary>効果・条件の詳細</summary><p>${esc(s.detail)}</p></details></article>`).join(''):empty()}
function bindSkills(){$('skill-query').value=currentParams.get('q')||'';$('skill-disc').value=currentParams.get('disc')||'';$('skill-level').value=currentParams.get('level')||'';for(const id of ['skill-query','skill-disc','skill-level'])$(id).addEventListener('input',()=>{setParam({q:$('skill-query').value,disc:$('skill-disc').value,level:$('skill-level').value});renderSkills()});$('skill-reset').onclick=()=>{['skill-query','skill-disc','skill-level'].forEach(id=>$(id).value='');setParam({q:'',disc:'',level:''});renderSkills()};renderSkills()}
const field=(name,label,value=0,max=1000000,min=0,step='any')=>`<label class="field">${label}<input name="${name}" type="number" value="${value}" min="${min}" max="${max}" step="${step}" required></label>`;
const check=(name,label,checked=false)=>`<label><input type="checkbox" name="${name}" ${checked?'checked':''}> ${label}</label>`;
function combat(){return `${heading('COMBAT LAB','戦闘・ダメージ計算機','条件を変えて、一撃のダメージと補正の順序を確かめる。')}<div class="filters"><button class="chip-button" id="mode-attack">与ダメージ</button><button class="chip-button" id="mode-defense">被ダメージ</button><a class="text-link" href="#combat?section=damage-formulas">詳しい計算式を読む ↓</a></div><div class="grid2"><form class="panel" id="damage-form" style="margin-top:0"></form><div><div id="damage-result" class="result" aria-live="polite"></div><div id="damage-trace"></div></div></div>${RPGGuides.combatText()}`}
let damageMode='attack';
function damageForm(){return damageMode==='attack'?`<h3>基本の攻撃条件</h3><div class="form-grid">${field('base','素のダメージ',10)}${field('str','有効STR（料理込み）',20)}${field('flat','剛力（固定加算）',3)}${field('rate','攻勢 %',25,100000)}${field('crit','装備の会心率 %',20,100)}${field('critPower','装備の会心強化 %',30,100000)}${field('agi','有効AGI（料理込み）')}${field('defense','敵の防御率 %',35,80)}<label class="field">武器<select name="weapon">${options(Object.fromEntries(Object.entries(R.gearTypes).slice(0,7)))}</select></label><label class="field">攻撃の種類<select name="cause"><option value="melee">近接</option><option value="projectile">飛び道具</option></select></label></div><div class="checks">${check('solid','敵の強固')}${check('pierce','貫通が発動')}${check('lethal','必殺の薬が発動')}</div><details><summary>生産スキル・呪い・吸命</summary><div class="form-grid">${field('vanilla','バニラ経験値レベル',0,24791)}${field('pieces','急所の細工の部位数',0,6,0,1)}${field('strike','経験の一撃の固定加算')}${field('dull','鈍刃 %',0,90)}${field('misfire','気まぐれの確率 %',0,50)}${field('lifesteal','吸命 %',0,50)}</div><div class="checks">${check('craft','製作の技（武器+1）')}${check('enchanted','魔力の刃（条件成立）')}${check('knowledge','知識の護りを習得')}${check('critKnowledge','知識の一撃を習得')}${check('axe','斧の心得を習得')}${check('outburst','癇癪が発動')}${check('failed','今回の攻撃は気まぐれで不発')}</div></details><details><summary>状態異常連携・特殊攻撃</summary><p class="small">チェックした特殊攻撃は発動済みとして計算。対応しない武器・攻撃の組み合わせには適用しません。</p><div class="form-grid">${field('blood','血響 %',0,100000)}${field('frost','氷砕 %',0,100000)}${field('stun','震撃 %',0,100000)}${field('weakness','心砕 %',0,100000)}${field('afflictions','有害効果の種類数',0,9,0,1)}</div><div class="checks">${check('bleeding','相手が裂傷中')}${check('slow','相手が移動速度低下中')}${check('stunned','相手が独自の眩暈中')}${check('weak','相手が弱体化中')}${check('chain','連鎖破砕あり')}${check('holy','聖矢が発動')}${check('blast','爆裂矢が発動')}${check('lightning','雷撃が発動')}${check('cleave','薙ぎ払いが発動')}</div></details><button type="reset">初期値に戻す</button>`:`<h3>敵の攻撃とプレイヤーの防御</h3><div class="form-grid">${field('base','素のダメージ',10)}${field('enemyAttack','敵の攻撃倍率',2,5,1)}${field('enemyCrit','敵の会心率 %',20,40)}${field('enemyCritMultiplier','敵の会心倍率',2,3,1)}${field('critResist','会心耐性 %',0,100)}${field('critReduction','致命傷軽減 %',0,100)}${field('armorFlat','堅牢（固定軽減）')}${field('guard','守勢 %',0,80)}${field('str','有効STR（料理込み）',0,166)}${field('dodge','身かわし率 %',0,30)}${field('block','受け流し率 %',0,40)}${field('vanilla','バニラ経験値レベル',0,24791)}</div><div class="checks">${check('shield','盾を装備')}${check('knowledge','知識の護りを習得')}${check('fullset','製作の技・防具4部位')}</div><details><summary>今回の回避・反撃・致死判定</summary><div class="form-grid">${field('thorns','反撃強化 %',0,100000)}${field('hp','現在HP',20,1000000,.1)}</div><div class="checks">${check('evaded','身かわしが成功')}${check('parried','受け流しが成功')}${check('potionDodge','身かわしの薬が有効')}${check('immortal','不死の薬が有効・再使用待ちなし')}</div><p class="small">反撃量は反撃発動時の値を表示。不死の薬は有効期間内で、30分の再使用待ちがない状態を指定します。</p></details><button type="reset">初期値に戻す</button>`}
function updateDamage(){const form=$('damage-form');if(!form.checkValidity()){$('damage-result').innerHTML='<p class="bad">入力値を確認してください。空欄や範囲外の値は計算できません。</p>';$('damage-trace').innerHTML='';return}const o={};for(const el of form.elements){if(!el.name)continue;o[el.name]=el.type==='checkbox'?el.checked:el.type==='number'?Number(el.value):el.value}try{const result=RPGCalc[damageMode](o);$('damage-result').innerHTML=`<div class="eyebrow">${damageMode==='attack'?'与ダメージ':'被ダメージ'} / 主対象の一撃</div><div class="result-grid"><div><span class="small">通常時</span><br><strong>${fmt(result.normal.value)}</strong></div><div><span class="small">会心時</span><br><strong>${fmt(result.critical.value)}</strong></div><div><span class="small">条件付き期待値</span><br><strong>${fmt(result.expected)}</strong></div></div><p class="small" style="margin-top:16px">実効会心率 ${fmt(result.chance*100)}%${result.criticalMultiplier?' ／ 会心倍率 ×'+fmt(result.criticalMultiplier):''}</p><p class="small">${damageMode==='attack'?'特殊攻撃などの発動条件を固定し、会心率と気まぐれの確率だけで平均。敵の反撃・継続ダメージは含みません。':'回避・不死の薬などのチェック条件を固定し、会心率・身かわし率・盾の受け流し率で平均。'}</p>`;$('damage-trace').innerHTML=`<div class="panel"><h3>会心した場合の途中式</h3><ol class="trace">${result.critical.trace.map(t=>`<li><strong>${t.label}</strong><br>${esc(t.formula.replace(/\d+\.\d{4,}/g,n=>fmt(Number(n))))}<br><span class="good">= ${fmt(t.value)}</span></li>`).join('')}</ol>${damageMode==='attack'?`<p class="small">会心時の吸命回復：${fmt(result.critical.heal)}<br>癇癪の自傷：${fmt(result.critical.self)}${result.critical.secondary.cleave.length?'<br>薙ぎ払いの副対象：'+result.critical.secondary.cleave.map(fmt).join(' / '):''}${result.critical.secondary.blast?'<br>爆裂矢の副対象1体：'+fmt(result.critical.secondary.blast):''}</p>`:`<p class="small">会心被弾・反撃発動時の反撃ダメージ：${fmt(result.critical.thorns)}</p>`}</div>`;return result}catch(e){$('damage-result').innerHTML=`<p class="bad">${esc(e.message)}</p>`;$('damage-trace').innerHTML=''}}
function bindCombat(){damageMode=currentParams.get('mode')==='defense'?'defense':'attack';const show=()=>{$('damage-form').innerHTML=damageForm();$('mode-attack').classList.toggle('active',damageMode==='attack');$('mode-defense').classList.toggle('active',damageMode==='defense');$('mode-attack').setAttribute('aria-pressed',damageMode==='attack');$('mode-defense').setAttribute('aria-pressed',damageMode==='defense');$('damage-form').oninput=updateDamage;$('damage-form').onsubmit=e=>e.preventDefault();$('damage-form').onreset=()=>setTimeout(updateDamage,0);updateDamage()};$('mode-attack').onclick=()=>{damageMode='attack';setParam({mode:'attack'});show()};$('mode-defense').onclick=()=>{damageMode='defense';setParam({mode:'defense'});show()};show()}
let searchIndex;
function buildIndex(){const entries=[];for(const [route,fn]of Object.entries({world:RPGGuides.world,player:RPGGuides.player,cooking:RPGGuides.cookingIntro,equipment:RPGGuides.equipmentIntro,combat:RPGGuides.combatText,production})){const tmp=document.createElement('div');tmp.innerHTML=fn();let group={title:NAV.find(n=>n[0]===route)[1],route,text:''};const walk=el=>{for(const ch of el.children){if(ch.tagName==='H2'){if(group.text)entries.push({...group});group={title:ch.textContent,route,text:'',section:ch.closest('section')?.id||''}}else if(['SCRIPT','INPUT','SELECT','BUTTON','NAV'].includes(ch.tagName))continue;else if(ch.querySelector('h2'))walk(ch);else group.text+=' '+ch.textContent}};walk(tmp);if(group.text)entries.push(group)}for(const f of R.foods)entries.push({title:f.name,route:'cooking',query:f.name,text:`${CATEGORIES[f.category]} 栄養${f.nutrition} ${SPECIALS[f.special]||''} `+f.pool.map(p=>{const e=effectInfo(p);return e.name+' '+e.strength+' '+e.time}).join(' / ')});for(const s of R.skills)entries.push({title:s.name,route:'production',query:s.name,disc:s.disc,text:`${s.discipline} Lv${s.level}${s.side} ${s.summary} ${s.operation} ${s.detail}`});for(const g of R.gear)entries.push({title:g.name,route:'equipment',query:g.name,text:`${GEAR_CATEGORIES[g.category]} ${g.description} ${g.types.map(t=>R.gearTypes[t]).join(' ')}`});return entries}
function searchPage(){const q=currentParams.get('q')||'';if(!searchIndex)searchIndex=buildIndex();const hits=q.trim()?searchIndex.filter(e=>matches(e.title+' '+e.text,q)).sort((a,b)=>Number(matches(b.title,q))-Number(matches(a.title,q))):[];return `${heading('SEARCH THE HANDBOOK','マニュアルを検索','食材・能力・スキル・解説をまとめて検索。ひらがな・カタカナのどちらでも検索できます。')}<p class="count">${q?'「'+esc(q)+'」：'+hits.length+'件':'上の検索欄に言葉を入力してください。'}</p><div id="search-results">${hits.slice(0,searchLimit).map(e=>{const p=new URLSearchParams();if(e.query)p.set('q',e.query);if(e.disc)p.set('disc',e.disc);if(e.section)p.set('section',e.section);const start=Math.max(0,normalize(e.text).indexOf(normalize(q))-35);return `<a class="search-hit" href="#${e.route}${p.size?'?'+p.toString():''}"><span class="badge">${NAV.find(n=>n[0]===e.route)[1]}</span><h3>${esc(e.title)}</h3><p>${esc(e.text.slice(start,start+180))}${e.text.length>start+180?'…':''}</p></a>`}).join('')|| (q?empty():'') }</div>${hits.length>searchLimit?'<button id="more-search">さらに表示</button>':''}`}
function route(focus=true){const raw=location.hash.slice(1)||'home',index=raw.indexOf('?');currentPage=index<0?raw:raw.slice(0,index);currentParams=new URLSearchParams(index<0?'':raw.slice(index+1));let html;if(currentPage==='home')html=HOME;else if(currentPage==='world'||currentPage==='player'||currentPage==='about')html=RPGGuides[currentPage]();else if(currentPage==='production')html=production();else if(currentPage==='cooking')html=RPGGuides.cookingIntro();else if(currentPage==='equipment')html=RPGGuides.equipmentIntro();else if(currentPage==='combat')html=combat();else if(currentPage==='search')html=searchPage();else html=heading('PAGE NOT FOUND','ページが見つかりません','<a href="#home">冒険の手引きに戻る →</a>');$('main').innerHTML=html;$('nav').innerHTML=NAV.map(([id,n,i])=>`<a href="#${id}" ${id===currentPage?'class="active" aria-current="page"':''}><span aria-hidden="true">${i}</span>${n}</a>`).join('');const title=NAV.find(n=>n[0]===currentPage)?.[1]||(currentPage==='about'?'このマニュアルについて':currentPage==='search'?'検索結果':'ページなし');$('crumb').textContent=title;document.title=title+' | RPGsystem';document.body.classList.remove('menu-open');$('menu').setAttribute('aria-expanded','false');if(currentPage==='cooking')bindFoods();if(currentPage==='equipment')bindGear();if(currentPage==='production')bindSkills();if(currentPage==='combat')bindCombat();if(currentPage==='search'){$('global-search').value=currentParams.get('q')||'';if($('more-search'))$('more-search').onclick=()=>{searchLimit+=40;const y=window.scrollY;route(false);window.scrollTo(0,y)}}else if(focus)$('global-search').value='';if(focus&&currentPage!=='search'){$('main').focus({preventScroll:true});window.scrollTo(0,0)}const section=currentParams.get('section');if(section)requestAnimationFrame(()=>$(section)?.scrollIntoView());}
$('search-form').onsubmit=e=>{e.preventDefault();searchLimit=40;location.hash='search?q='+encodeURIComponent($('global-search').value)};
let searchTimer;$('global-search').addEventListener('input',()=>{clearTimeout(searchTimer);searchTimer=setTimeout(()=>{searchLimit=40;const q=$('global-search').value;history.replaceState(null,'','#search?q='+encodeURIComponent(q));route(false)},180)});
$('menu').onclick=()=>{const open=document.body.classList.toggle('menu-open');$('menu').setAttribute('aria-expanded',String(open))};
document.addEventListener('keydown',e=>{if(e.key==='/'&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)){e.preventDefault();$('global-search').focus()}if(e.key==='Escape'){document.body.classList.remove('menu-open');$('menu').setAttribute('aria-expanded','false')}});
// 本文へのスキップリンクはページ切り替えをせず、本文へキーボードフォーカスを移す。
document.querySelector('.skip').onclick=e=>{e.preventDefault();$('main').focus()};
// 閉じたスマートフォン用メニューへTabキーが入り込まないようにする。
const mobileMenu=window.matchMedia('(max-width:760px)');
const syncMenu=()=>{$('sidebar').inert=mobileMenu.matches&&!document.body.classList.contains('menu-open')};
mobileMenu.addEventListener('change',syncMenu);
new MutationObserver(syncMenu).observe(document.body,{attributes:true,attributeFilter:['class']});
window.addEventListener('hashchange',()=>route());route(false);syncMenu();
// ブラウザが対応している場合だけ、検索操作をAIにも公開。同じ画面・同じ絞り込み処理を使う。
if(document.modelContext?.registerTool){const lifecycle=new AbortController();try{Promise.resolve(document.modelContext.registerTool({name:'search_food_catalog',title:'料理食材を検索',description:'料理食材の検索画面を開き、食材名・効果名と分類で絞り込み、候補を返す。',inputSchema:{type:'object',properties:{query:{type:'string',maxLength:100},category:{type:'string',enum:['','crop','fish','meat','other']}},required:['query'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){if(!input||typeof input.query!=='string'||input.query.length>100||Object.keys(input).some(k=>!['query','category'].includes(k))||input.category!==undefined&&!['','crop','fish','meat','other'].includes(input.category))throw Error('検索条件が不正です');const params=new URLSearchParams({q:input.query});if(input.category)params.set('category',input.category);history.pushState(null,'','#cooking?'+params);route();const arr=filterFoods();return {count:arr.length,items:arr.map(f=>({name:f.name,category:CATEGORIES[f.category],effects:f.pool.map(p=>effectInfo(p).name)}))}}},{signal:lifecycle.signal})).catch(()=>{});window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true})}catch{}}

